const resp = $input.first().json;
const cached = $('Get Cached').item.json;
const file = cached.file;

let outcome, config, new_etag = null;

if (resp.statusCode === 200) {
  try {
    config = JSON.parse(resp.body);
    outcome = 'fresh';
    const headers = resp.headers || {};
    new_etag = headers.etag || headers.ETag || null;
  } catch (e) {
    // 200 but not valid JSON -- treat exactly like a fetch failure
    if (cached.cached_body) {
      outcome = 'fallback_alarm';
      config = cached.cached_body;
    } else {
      outcome = 'hard_fail_alarm';
      config = null;
    }
  }
} else if (resp.statusCode === 304) {
  outcome = 'cached_not_modified';
  config = cached.cached_body;
} else if (cached.cached_body) {
  outcome = 'fallback_alarm';
  config = cached.cached_body;
} else {
  outcome = 'hard_fail_alarm';
  config = null;
}

return [{ json: { file, config, outcome, new_etag, statusCode: resp.statusCode || null } }];

const decided = $('Decide Outcome').item.json;

if (decided.outcome === 'hard_fail_alarm') {
  throw new Error('WF-L0: config fetch failed for ' + decided.file + ' and no cached fallback exists');
}

// NOTE: 'fallback_alarm' returns successfully (there IS usable cached data)
// but CLAUDE.md requires this to alarm, not just silently degrade. WF-5
// (Phase 3) isn't wired yet -- once it is, alarm on outcome === 'fallback_alarm'
// here, not just on hard failure.
return [{ json: { file: decided.file, config: decided.config, outcome: decided.outcome } }];
